"""Compiled "test_output" dimension. GENERATED by solution/recompute.py.

Registers one real @rk.criterion per deterministic ARE-verifier fact through the real factory
(rk.are_fact(fact, weight=...)): one per unambiguous oracle write, one per rigid argument that
carries signal, the tool-name-count precheck, causality, one no_guess per ambiguity, and message
sanity. Each is a hard match against TRUTH.md values via the stdlib engine in are_verifier.py; no
free text is graded here (the report prose and message bodies are the separate judge dimension).
Each no_guess fact carries the highest weight; all weights normalize within this dimension, so the
absolute total is cosmetic. The cross-dimension split is set by [judge].weight (test_output 80% :
judge 20%), not by these weights.
"""
import json
import sys
from pathlib import Path

import rewardkit as rk

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
sys.dont_write_bytecode = True
import are_verifier

ORACLE = json.loads((HERE / "oracle.json").read_text(encoding="utf-8"))
_CACHE = {}


def _facts(workspace):
    key = str(Path(workspace).resolve())
    if key not in _CACHE:
        _CACHE[key] = are_verifier.grade(Path(workspace), ORACLE)["facts"]
    return _CACHE[key]


@rk.criterion(description="ARE compiled fact: {fact}")
def are_fact(workspace: Path, fact: str) -> float:
    return 1.0 if _facts(workspace)[fact]["pass"] else 0.0


for _fact, _weight in ORACLE["compiled_weights"].items():
    rk.are_fact(_fact, weight=float(_weight))
